urlset:
{% for page in pages %}

  {{ domain }}/{{ page }}
  daily
  0.8

{% endfor %}
{% for category in categories %}

  {{ domain }}{% url 'store:category_products' category.slug %}
  weekly
  0.7

{% endfor %}
{% for product in products %}

  {{ domain }}{% url 'store:product_detail' product.slug %}
  {{ product.updated_at|date:"Y-m-d" }}
  weekly
  0.6

{% endfor %}
